/* SentiLab deck. Slides are authored once at 1920x1080 and scaled to the window.
 *
 * Every value on a slide comes from deck-data.json (generated by the build-deck-data script from the dated progress packet):
 *   <span data-f="gb10.steps"></span>        the fact's display text; PENDING when the packet has no value
 *   <span data-asof="key key"></span>        "as of <time> · <source>" for those facts
 *   <div data-gen="deliverables"></div>      a list generated from deck-data lists
 *   <footer data-gen="sources"></footer>     the source times of everything on the slide not already stamped
 * renderHtml() is a pure string function, so the node test renders exactly what the browser renders.
 *
 * Keys: Right/Down/Space/PageDown next · Left/Up/PageUp previous · Home/End · F fullscreen · N speaker notes.
 * ?print=1 lays every slide out as a 1920x1080 page (the export-deck-pdf script prints it to PDF).
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else { root.Deck = api; if (root.document) api.boot(root); }
})(typeof window !== "undefined" ? window : globalThis, function () {
  "use strict";
  const PENDING = "— (pending freeze)";
  const W = 1920, H = 1080;
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const addClass = (attrs, cls) => (/\bclass="/.test(attrs) ? attrs.replace(/\bclass="([^"]*)"/, (m, c) => `class="${c} ${cls}"`) : `${attrs} class="${cls}"`);
  const STATUS = { done: "done", measured: "measured", open: "open", superseded: "superseded" };
  const pill = (status) => `<span class="pill st-${esc(STATUS[status] ? status : "unknown")}">${esc(status ?? PENDING)}</span>`;
  const tsKey = (t) => t || "";

  // ── generated blocks ──────────────────────────────────────────────────────────────────────────────────────────────
  const GEN = {
    deliverables(data, note) {
      const rows = (data.lists?.deliverables ?? []).map((d) => {
        note("deliverable ledger", d.asOf);
        return `<li class="dl st-${esc(d.status)}"><span class="dl-id">${esc(d.id)}</span><span class="dl-t">${esc(d.title)}</span>${pill(d.status)}</li>`;
      });
      return rows.length ? rows.join("") : `<li class="pending">${esc(data.pending ?? PENDING)}</li>`;
    },
    progress(data, note) {
      const groups = [["done", "Done · scoped slices"], ["measured", "Measured"], ["open", "Open"]];
      return groups.map(([st, label]) => {
        const items = (data.lists?.milestones ?? []).filter((m) => m.status === st);
        items.forEach((m) => note("progress record", m.asOf));
        return `<div class="pg st-${st}"><h3>${esc(label)}</h3><ul>${items.length ? items.map((m) => `<li>${esc(m.title)}</li>`).join("") : `<li class="pending">${esc(data.pending ?? PENDING)}</li>`}</ul></div>`;
      }).join("");
    },
    priorities(data, note) {
      const items = data.lists?.priorities ?? [];
      items.forEach((m) => note("progress record", m.asOf));
      return items.length ? items.map((m) => `<li>${esc(m.title)}</li>`).join("") : `<li class="pending">${esc(data.pending ?? PENDING)}</li>`;
    },
    coverage(data, note) {
      const tickets = data.lists?.tickets ?? [];
      const dels = data.lists?.deliverables ?? [];
      if (!tickets.length || !dels.length) return `<div class="pending">${esc(data.pending ?? PENDING)}</div>`;
      const chip = (t) => { note("ticket ledger", t.asOf); return `<span class="tk st-${esc(t.status)}${t.optional ? " opt" : ""}" title="${esc(t.id)} · ${esc(t.status)}">${esc(t.n)}</span>`; };
      const byId = new Map(tickets.map((t) => [t.id, t]));
      const rows = dels.map((d) => {
        note("deliverable ledger", d.asOf);
        const ts = (d.tickets ?? []).map((id) => byId.get(id)).filter(Boolean);
        return `<div class="cv-row"><div class="cv-d st-${esc(d.status)}"><b>${esc(d.id)}</b>${pill(d.status)}</div><div class="cv-t">${ts.map(chip).join("")}</div></div>`;
      });
      const mapped = new Set(dels.flatMap((d) => d.tickets ?? []));
      const rest = tickets.filter((t) => !mapped.has(t.id));
      rows.push(`<div class="cv-row cv-rest"><div class="cv-d"><b>Shared</b><span class="cv-sub">cross-cutting</span></div><div class="cv-t">${rest.map(chip).join("")}</div></div>`);
      return rows.join("");
    },
    legend(data) {
      const lg = data.lists?.statusLegend ?? {};
      return ["measured", "open"].filter((k) => lg[k]).map((k) => `<p><span class="pill st-${k}">${esc(k)}</span>${esc(lg[k])}</p>`).join("");
    },
  };

  // ── rendering ─────────────────────────────────────────────────────────────────────────────────────────────────────
  function renderSection(sec, data) {
    const facts = data.facts ?? {};
    const pending = data.pending ?? PENDING;
    const used = [];            // { key, label, asOf } for facts shown on this slide
    const listed = [];          // { label, asOf } for generated lists
    const stamped = new Set();  // "source|time" pairs already printed in a stamp on this slide
    const note = (label, asOf) => listed.push({ label, asOf });
    const sk = (source, asOf) => `${source}|${asOf}`;

    sec = sec.replace(/<(span|b|strong|em|i|div|p|h1|h2|h3|li)\b([^>]*?)\sdata-f="([\w.]+)"([^>]*)>\s*<\/\1>/g, (m, tag, pre, key, post) => {
      const f = facts[key];
      const missing = !f || f.value == null;
      if (f) used.push({ key, label: f.source, asOf: f.asOf });
      const attrs = `${pre} data-f="${key}"${post}${f ? ` title="as of ${esc(f.asOf)} · ${esc(f.source)}"` : ""}`;
      return `<${tag}${missing ? addClass(attrs, "pending") : attrs}>${esc(missing ? (f?.display ?? pending) : f.display)}</${tag}>`;
    });
    sec = sec.replace(/<(span|div|p)\b([^>]*?)\sdata-asof="([\w. ]+)"([^>]*)>\s*<\/\1>/g, (m, tag, pre, keys, post) => {
      const seen = new Set(), parts = [];
      for (const k of keys.trim().split(/\s+/)) {
        const f = facts[k];
        if (!f || seen.has(sk(f.source, f.asOf))) continue;
        seen.add(sk(f.source, f.asOf));
        stamped.add(sk(f.source, f.asOf));
        parts.push(`<span class="st-i">${esc(f.source)} · ${esc(f.asOf)}</span>`);
      }
      return `<${tag}${pre} data-asof="${keys}"${post}>${parts.length ? `<span class="st-h">as of</span>${parts.join("")}` : esc(pending)}</${tag}>`;
    });
    sec = sec.replace(/<(div|ul|ol)\b([^>]*?)\sdata-gen="(\w+)"([^>]*)>\s*<\/\1>/g, (m, tag, pre, name, post) => {
      if (!GEN[name]) return m;
      return `<${tag}${pre} data-gen="${name}"${post}>${GEN[name](data, note)}</${tag}>`;
    });
    sec = sec.replace(/<(footer)\b([^>]*?)\sdata-gen="sources"([^>]*)>\s*<\/\1>/, (m, tag, pre, post) => {
      // Per source: every distinct time of a fact shown here; list items (no numbers) may collapse to a range.
      const byLabel = new Map();
      const entry = (label) => byLabel.get(label) ?? byLabel.set(label, { facts: new Set(), all: new Set() }).get(label);
      for (const u of used.filter((u) => !stamped.has(sk(u.label, u.asOf)))) { entry(u.label).facts.add(u.asOf); entry(u.label).all.add(u.asOf); }
      for (const u of listed) if (u.asOf) entry(u.label).all.add(u.asOf);
      const sort = (set) => [...set].filter(Boolean).sort((a, b) => tsKey(a).localeCompare(tsKey(b)));
      const parts = [...byLabel].map(([label, { facts: ft, all }]) => {
        const t = sort(all);
        let when = t.length === 0 ? pending : t.length <= 3 ? t.join(", ") : `${t[0]} to ${t[t.length - 1]}`;
        if (t.length > 3) { const inner = sort(ft).filter((x) => x !== t[0] && x !== t[t.length - 1]); if (inner.length) when += `; values ${inner.join(", ")}`; }
        return `<span class="src-i"><b>${esc(label)}</b> ${esc(when)}</span>`;
      });
      const body = parts.length ? `<span class="src-h">Data</span>${parts.join("")}` : `<span class="src-h">Data</span><span class="src-i">every value on this slide is stamped with its source time</span>`;
      return `<${tag}${pre} data-gen="sources"${post}>${body}</${tag}>`;
    });
    return sec;
  }
  function renderHtml(html, data) {
    return html.replace(/<section\b[^>]*\bclass="slide\b[^"]*"[^>]*>[\s\S]*?<\/section>/g, (sec) => renderSection(sec, data));
  }

  // ── browser ───────────────────────────────────────────────────────────────────────────────────────────────────────
  function boot(win) {
    const doc = win.document;
    const start = () => run(win).catch((e) => {
      doc.body.insertAdjacentHTML("afterbegin", `<p class="fatal">Deck data could not be loaded: ${esc(e.message)}</p>`);
    });
    if (doc.readyState === "loading") doc.addEventListener("DOMContentLoaded", start); else start();
  }
  async function loadData(win) {
    // Served over http(s): read deck-data.json. Opened from disk (file:, where fetch is refused): use the generated
    // script copy, which the node test proves is the same object.
    if (win.location.protocol !== "file:") {
      try {
        const r = await win.fetch("deck-data.json", { cache: "no-store" });
        if (r.ok) return { data: await r.json(), from: "deck-data.json" };
      } catch { /* offline: fall back to the script copy */ }
    }
    if (win.DECK_DATA) return { data: win.DECK_DATA, from: "deck-data.js" };
    throw new Error("neither deck-data.json nor deck-data.js is available");
  }
  async function run(win) {
    const doc = win.document;
    const params = new win.URLSearchParams(win.location.search);
    const { data, from } = await loadData(win);
    const deck = doc.getElementById("deck");
    deck.innerHTML = renderHtml(deck.innerHTML, data);
    const slides = [...deck.querySelectorAll(".slide")];
    const notesById = new Map((data.notes ?? []).map((n) => [n.slide, n]));
    const notesEl = doc.getElementById("notes");
    const print = params.has("print");
    let i = 0, t0 = Date.now();

    if (print) doc.body.classList.add("print");
    const fit = () => deck.style.setProperty("--s", String(Math.min(win.innerWidth / W, win.innerHeight / H)));
    fit();
    win.addEventListener("resize", fit);

    const label = (k) => slides[k].dataset.label || "";
    function renderNotes() {
      const n = notesById.get(slides[i].dataset.notes);
      const s = Math.floor((Date.now() - t0) / 1000);
      notesEl.querySelector(".n-pos").textContent = `${label(i)} · ${slides[i].dataset.title || ""}`;
      notesEl.querySelector(".n-target").textContent = n ? `target ${n.target}` : "";
      notesEl.querySelector(".n-clock").textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")} elapsed`;
      notesEl.querySelector(".n-text").textContent = n ? n.text : "";
    }
    function show(k, push = true) {
      i = Math.max(0, Math.min(slides.length - 1, k));
      slides.forEach((s, j) => s.classList.toggle("on", j === i));
      if (push) win.history.replaceState(null, "", `#${i + 1}`);
      renderNotes();
    }
    const fromHash = () => { const n = parseInt(win.location.hash.slice(1), 10); return Number.isFinite(n) ? n - 1 : 0; };
    win.addEventListener("hashchange", () => show(fromHash(), false));
    win.addEventListener("keydown", (e) => {
      if (e.altKey || e.ctrlKey || e.metaKey) return;
      const k = e.key;
      if (["ArrowRight", "ArrowDown", " ", "PageDown", "Enter"].includes(k)) { e.preventDefault(); show(i + 1); }
      else if (["ArrowLeft", "ArrowUp", "PageUp", "Backspace"].includes(k)) { e.preventDefault(); show(i - 1); }
      else if (k === "Home") show(0);
      else if (k === "End") show(slides.length - 1);
      else if (k === "f" || k === "F") {
        if (doc.fullscreenElement) doc.exitFullscreen?.(); else doc.documentElement.requestFullscreen?.().catch(() => {});
      } else if (k === "n" || k === "N") { notesEl.hidden = !notesEl.hidden; renderNotes(); }
      else if (k === "r" || k === "R") { t0 = Date.now(); renderNotes(); }
    });
    deck.addEventListener("click", (e) => {
      if (e.target.closest("a")) return;
      const r = deck.getBoundingClientRect();
      show(e.clientX < r.left + r.width / 3 ? i - 1 : i + 1);
    });
    win.setInterval(() => { if (!notesEl.hidden) renderNotes(); }, 1000);
    if (params.has("notes")) notesEl.hidden = false;
    show(fromHash(), false);
    win.__deck = { ready: true, from, count: slides.length, go: (k) => show(k), ids: slides.map((s) => s.id), labels: slides.map((s) => s.dataset.label) };
  }

  return { renderHtml, GEN, PENDING, esc, boot };
});
